import React from 'react';

const SearchBar = ({ searchTerm, setSearchTerm }) => {
  return (
    <input
      type="text"
      placeholder="Enter version name..."
      value={searchTerm}
      onChange={(e) => setSearchTerm(e.target.value)}
      style={{
        padding: '8px',
        margin: '10px 0',
        borderRadius: '8px',
        border: '1px solid #ccc',
        width: '100%'
      }}
    />
  );
};

export default SearchBar;
